1	package main
2	
3	import (
4		"errors"
5		"flag"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10	)
11	
12	const appName = "caretrack"
13	
14	const helpText = `caretrack — 本地设备资产登记与维修工单闭环工具
15	
16	数据保存在本地目录，无外部服务依赖，仅支持单进程顺序调用。
17	
18	用法:
19	  caretrack <命令> [参数]
20	
21	命令:
22	  register   登记资产（企业资产编号、名称、位置）
23	  list       列出全部资产及当前状态
24	  detail     查看资产详情及其未关闭工单编号
25	  report     对资产报修，创建工单，资产转为“维修中”
26	  assign     为未关闭工单派工或转派维修人员
27	  ticket     按工单编号查询工单状态与负责人
28	  close      关闭工单并填写维修结果，设备恢复“可用”
29	  cancel     取消误报或不再需要维修的未关闭工单，设备恢复“可用”
30	  history    按资产查看维修履历（报修、派工、关闭、取消事件）
31	  help       显示本帮助
32	
33	各命令参数:
34	  register --asset-id 编号 --name 名称 --location 位置 [--data-dir 目录]
35	  list                                                        [--data-dir 目录]
36	  detail   --asset-id 编号                                    [--data-dir 目录]
37	  report   --asset-id 编号 --description 故障描述 --request-id 请求标识
38	                                                              [--data-dir 目录]
39	  assign   --ticket-id 工单编号 --assignee 维修人员 --note 说明  [--data-dir 目录]
40	  ticket   --ticket-id 工单编号                                 [--data-dir 目录]
41	  close    --ticket-id 工单编号 --repair-result 维修结果       [--data-dir 目录]
42	  cancel   --ticket-id 工单编号 --reason 取消理由              [--data-dir 目录]
43	  history  --asset-id 编号                                    [--data-dir 目录]
44	
45	通用参数:
46	  --data-dir 目录   本地数据目录，默认 ".caretrack"；不同目录数据互不影响，
47	                    目录不存在时会在首次成功写入时自动初始化
48	
49	业务规则:
50	  - 资产编号、名称、位置均不能为空；同一数据目录内资产编号唯一，新资产为“可用”。
51	  - 每项资产最多有一张未关闭工单；未知资产、空故障描述、资产已有未关闭工单时
52	    报修失败，不改变状态与履历。
53	  - --request-id 由调用方提供且非空，仅用于同一数据目录内的报修去重，不作为
54	    资产或工单编号：相同标识、资产、描述再次提交返回原工单及当前状态，不新增
55	    记录；同一标识搭配不同资产或描述将被拒绝；原工单关闭或取消后重放仍返回原工单，
56	    不重开旧单，也不影响新单。
57	  - 仅未关闭工单可派工：没有负责人时首次派工，已有负责人时转派给不同人员。
58	    维修人员标识只是本地文本记录（非人员账户），与派工说明均不能为空；
59	    成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为
60	    “未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单编号，
61	    不改变资产状态或报修请求绑定；未知工单、空人员或说明、重复派给当前
62	    人员、对已关闭或已取消工单派工均失败且不产生履历。工单关闭或取消后
63	    保留最后负责人与派工履历。
64	  - 仅未关闭工单可关闭，维修结果不能为空；未知工单、重复关闭均失败。
65	  - 仅未关闭工单可取消，取消理由不能为空；取消后工单进入“已取消”终态，保存取消
66	    理由与时间，资产恢复“可用”，可再次报修。取消不代表维修完成，不填写维修结果，
67	    不删除工单、履历或请求绑定，工单编号不回退也不复用；已取消工单不能关闭或再次
68	    取消，已关闭工单也不能取消。
69	
70	无参数、--help、-h 显示本帮助；参数错误或业务失败以非零退出码结束并说明原因。
71	`
72	
73	type cmdOptions struct {
74		dataDir string
75	}
76	
77	func printHelp(w io.Writer) {
78		fmt.Fprint(w, helpText)
79	}
80	
81	func main() {
82		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
83	}
84	
85	func run(args []string, stdout, stderr io.Writer) int {
86		if len(args) == 0 {
87			printHelp(stdout)
88			return 0
89		}
90		switch args[0] {
91		case "--help", "-h", "help":
92			if len(args) > 1 {
93				fmt.Fprintf(stderr, "%s: help 不接受额外参数\n", appName)
94				return 2
95			}
96			printHelp(stdout)
97			return 0
98		}
99	
100		var err error
101		switch args[0] {
102		case "register":
103			err = cmdRegister(args[1:], stdout)
104		case "list":
105			err = cmdList(args[1:], stdout)
106		case "detail":
107			err = cmdDetail(args[1:], stdout)
108		case "report":
109			err = cmdReport(args[1:], stdout)
110		case "assign":
111			err = cmdAssign(args[1:], stdout)
112		case "ticket":
113			err = cmdTicket(args[1:], stdout)
114		case "close":
115			err = cmdClose(args[1:], stdout)
116		case "cancel":
117			err = cmdCancel(args[1:], stdout)
118		case "history":
119			err = cmdHistory(args[1:], stdout)
120		default:
121			fmt.Fprintf(stderr, "%s: 未知命令 %q，使用 --help 查看帮助\n", appName, args[0])
122			return 2
123		}
124		if err != nil {
125			if errors.Is(err, flag.ErrHelp) {
126				return 0
127			}
128			var ue *usageError
129			if errors.As(err, &ue) {
130				fmt.Fprintf(stderr, "%s: %s\n", appName, ue.Error())
131				return 2
132			}
133			fmt.Fprintf(stderr, "%s: %s\n", appName, friendlyErr(err.Error()))
134			return 1
135		}
136		return 0
137	}
138	
139	// friendlyErr 去掉内部哨兵错误（errNotFound/errConflict）的英文前缀。
140	func friendlyErr(msg string) string {
141		for _, p := range []string{"not found: ", "conflict: "} {
142			if strings.HasPrefix(msg, p) {
143				return msg[len(p):]
144			}
145		}
146		return msg
147	}
148	
149	type usageError struct{ msg string }
150	
151	func (e *usageError) Error() string { return e.msg }
152	
153	// newFlagSet 为子命令准备参数解析器：--help/-h 输出帮助并返回 flag.ErrHelp，
154	// 其余参数错误转成 *usageError（退出码 2）。
155	func newFlagSet(name string, opts *cmdOptions) *flag.FlagSet {
156		fs := flag.NewFlagSet(name, flag.ContinueOnError)
157		fs.SetOutput(os.Stdout)
158		fs.Usage = func() {
159			fmt.Fprintf(os.Stdout, "用法: caretrack %s [参数]\n\n", name)
160			fs.PrintDefaults()
161		}
162		fs.StringVar(&opts.dataDir, "data-dir", ".caretrack", "本地数据目录")
163		return fs
164	}
165	
166	func parseFlags(fs *flag.FlagSet, args []string) error {
167		if err := fs.Parse(args); err != nil {
168			if errors.Is(err, flag.ErrHelp) {
169				return err
170			}
171			return &usageError{msg: err.Error()}
172		}
173		if fs.NArg() > 0 {
174			return &usageError{msg: fmt.Sprintf("命令 %s 不接受位置参数: %v", fs.Name(), fs.Args())}
175		}
176		return nil
177	}
178	
179	func requireFlag(fs *flag.FlagSet, value, flagName string) error {
180		if value == "" {
181			return &usageError{msg: fmt.Sprintf("命令 %s 缺少必填参数 --%s", fs.Name(), flagName)}
182		}
183		return nil
184	}
185	
186	func cmdRegister(args []string, w io.Writer) error {
187		var opts cmdOptions
188		var id, name, location string
189		fs := newFlagSet("register", &opts)
190		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填，同一数据目录内唯一）")
191		fs.StringVar(&name, "name", "", "资产名称（必填）")
192		fs.StringVar(&location, "location", "", "资产位置（必填）")
193		if err := parseFlags(fs, args); err != nil {
194			return err
195		}
196		if err := requireFlag(fs, id, "asset-id"); err != nil {
197			return err
198		}
199		if err := requireFlag(fs, name, "name"); err != nil {
200			return err
201		}
202		if err := requireFlag(fs, location, "location"); err != nil {
203			return err
204		}
205	
206		s, err := openStore(opts.dataDir)
207		if err != nil {
208			return err
209		}
210		asset, err := s.registerAsset(id, name, location)
211		if err != nil {
212			return err
213		}
214		if err := s.save(); err != nil {
215			return err
216		}
217		fmt.Fprintf(w, "已登记资产 %s\n", asset.ID)
218		fmt.Fprintf(w, "名称: %s\n", asset.Name)
219		fmt.Fprintf(w, "位置: %s\n", asset.Location)
220		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
221		return nil
222	}
223	
224	func cmdList(args []string, w io.Writer) error {
225		var opts cmdOptions
226		fs := newFlagSet("list", &opts)
227		if err := parseFlags(fs, args); err != nil {
228			return err
229		}
230		s, err := openStore(opts.dataDir)
231		if err != nil {
232			return err
233		}
234		assets := s.data.Assets
235		if len(assets) == 0 {
236			fmt.Fprintln(w, "没有记录。")
237			return nil
238		}
239		fmt.Fprintf(w, "共 %d 项资产:\n", len(assets))
240		for _, a := range assets {
241			fmt.Fprintf(w, "%s\t%s\t%s\t%s\n", a.ID, a.Name, a.Location, a.Status)
242		}
243		return nil
244	}
245	
246	func cmdDetail(args []string, w io.Writer) error {
247		var opts cmdOptions
248		var id string
249		fs := newFlagSet("detail", &opts)
250		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
251		if err := parseFlags(fs, args); err != nil {
252			return err
253		}
254		if err := requireFlag(fs, id, "asset-id"); err != nil {
255			return err
256		}
257		s, err := openStore(opts.dataDir)
258		if err != nil {
259			return err
260		}
261		asset := s.findAsset(id)
262		if asset == nil {
263			return fmt.Errorf("未知资产编号 %q", id)
264		}
265		openTicket := s.openTicketOf(asset.ID)
266		fmt.Fprintf(w, "资产编号: %s\n", asset.ID)
267		fmt.Fprintf(w, "名称: %s\n", asset.Name)
268		fmt.Fprintf(w, "位置: %s\n", asset.Location)
269		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
270		if openTicket == nil {
271			fmt.Fprintln(w, "未关闭工单: 无")
272		} else {
273			fmt.Fprintf(w, "未关闭工单: %s\n", openTicket.ID)
274			fmt.Fprintf(w, "工单负责人: %s\n", assigneeDisplay(openTicket.Assignee))
275		}
276		return nil
277	}
278	
279	// assigneeDisplay 把空负责人显示为“未派工”。
280	func assigneeDisplay(assignee string) string {
281		if assignee == "" {
282			return "未派工"
283		}
284		return assignee
285	}
286	
287	func cmdReport(args []string, w io.Writer) error {
288		var opts cmdOptions
289		var assetID, description, requestID string
290		fs := newFlagSet("report", &opts)
291		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（必填）")
292		fs.StringVar(&description, "description", "", "故障描述（必填）")
293		fs.StringVar(&requestID, "request-id", "", "调用方提供的非空请求标识，用于报修去重（必填）")
294		if err := parseFlags(fs, args); err != nil {
295			return err
296		}
297		if err := requireFlag(fs, assetID, "asset-id"); err != nil {
298			return err
299		}
300		if err := requireFlag(fs, description, "description"); err != nil {
301			return err
302		}
303		if err := requireFlag(fs, requestID, "request-id"); err != nil {
304			return err
305		}
306	
307		s, err := openStore(opts.dataDir)
308		if err != nil {
309			return err
310		}
311		ticket, replayed, err := s.report(assetID, description, requestID)
312		if err != nil {
313			return err
314		}
315		if !replayed {
316			if err := s.save(); err != nil {
317				return err
318			}
319			fmt.Fprintf(w, "工单编号: %s\n", ticket.ID)
320		} else {
321			fmt.Fprintf(w, "该请求标识已提交过，返回原工单，未重复创建。\n")
322			fmt.Fprintf(w, "工单编号: %s（既有工单）\n", ticket.ID)
323		}
324		fmt.Fprintf(w, "资产编号: %s\n", ticket.AssetID)
325		fmt.Fprintf(w, "工单状态: %s\n", ticket.Status)
326		return nil
327	}
328	
329	func cmdAssign(args []string, w io.Writer) error {
330		var opts cmdOptions
331		var ticketID, assignee, note string
332		fs := newFlagSet("assign", &opts)
333		fs.StringVar(&ticketID, "ticket-id", "", "要派工的工单编号（必填）")
334		fs.StringVar(&assignee, "assignee", "", "维修人员标识（必填，本地文本记录，非人员账户）")
335		fs.StringVar(&note, "note", "", "派工说明（必填，非空）")
336		if err := parseFlags(fs, args); err != nil {
337			return err
338		}
339		if err := requireFlag(fs, ticketID, "ticket-id"); err != nil {
340			return err
341		}
342		if err := requireFlag(fs, assignee, "assignee"); err != nil {
343			return err
344		}
345		if err := requireFlag(fs, note, "note"); err != nil {
346			return err
347		}
348	
349		s, err := openStore(opts.dataDir)
350		if err != nil {
351			return err
352		}
353		ticket, err := s.assignTicket(ticketID, assignee, note)
354		if err != nil {
355			return err
356		}
357		if err := s.save(); err != nil {
358			return err
359		}
360		fmt.Fprintf(w, "工单编号: %s\n", ticket.ID)
361		fmt.Fprintf(w, "负责人: %s\n", ticket.Assignee)
362		return nil
363	}
364	
365	func cmdTicket(args []string, w io.Writer) error {
366		var opts cmdOptions
367		var ticketID string
368		fs := newFlagSet("ticket", &opts)
369		fs.StringVar(&ticketID, "ticket-id", "", "要查询的工单编号（必填）")
370		if err := parseFlags(fs, args); err != nil {
371			return err
372		}
373		if err := requireFlag(fs, ticketID, "ticket-id"); err != nil {
374			return err
375		}
376	
377		s, err := openStore(opts.dataDir)
378		if err != nil {
379			return err
380		}
381		t := s.findTicket(ticketID)
382		if t == nil {
383			return fmt.Errorf("未知工单编号 %q", ticketID)
384		}
385		fmt.Fprintf(w, "工单编号: %s\n", t.ID)
386		fmt.Fprintf(w, "资产编号: %s\n", t.AssetID)
387		fmt.Fprintf(w, "工单状态: %s\n", t.Status)
388		fmt.Fprintf(w, "负责人: %s\n", assigneeDisplay(t.Assignee))
389		if t.Assignee != "" {
390			fmt.Fprintf(w, "派工时间: %s\n", t.AssignedAt)
391			fmt.Fprintf(w, "派工说明: %s\n", t.AssignNote)
392		}
393		return nil
394	}
395	
396	func cmdClose(args []string, w io.Writer) error {
397		var opts cmdOptions
398		var ticketID, result string
399		fs := newFlagSet("close", &opts)
400		fs.StringVar(&ticketID, "ticket-id", "", "要关闭的工单编号（必填）")
401		fs.StringVar(&result, "repair-result", "", "维修结果（必填）")
402		if err := parseFlags(fs, args); err != nil {
403			return err
404		}
405		if err := requireFlag(fs, ticketID, "ticket-id"); err != nil {
406			return err
407		}
408		if err := requireFlag(fs, result, "repair-result"); err != nil {
409			return err
410		}
411	
412		s, err := openStore(opts.dataDir)
413		if err != nil {
414			return err
415		}
416		ticket, asset, err := s.closeTicket(ticketID, result)
417		if err != nil {
418			return err
419		}
420		if err := s.save(); err != nil {
421			return err
422		}
423		fmt.Fprintf(w, "工单 %s 已关闭。\n", ticket.ID)
424		fmt.Fprintf(w, "资产 %s 当前状态: %s\n", asset.ID, asset.Status)
425		return nil
426	}
427	
428	func cmdCancel(args []string, w io.Writer) error {
429		var opts cmdOptions
430		var ticketID, reason string
431		fs := newFlagSet("cancel", &opts)
432		fs.StringVar(&ticketID, "ticket-id", "", "要取消的工单编号（必填）")
433		fs.StringVar(&reason, "reason", "", "取消理由（必填，非空）")
434		if err := parseFlags(fs, args); err != nil {
435			return err
436		}
437		if err := requireFlag(fs, ticketID, "ticket-id"); err != nil {
438			return err
439		}
440		if err := requireFlag(fs, reason, "reason"); err != nil {
441			return err
442		}
443	
444		s, err := openStore(opts.dataDir)
445		if err != nil {
446			return err
447		}
448		ticket, asset, err := s.cancelTicket(ticketID, reason)
449		if err != nil {
450			return err
451		}
452		if err := s.save(); err != nil {
453			return err
454		}
455		fmt.Fprintf(w, "工单 %s 已取消。\n", ticket.ID)
456		fmt.Fprintf(w, "工单状态: %s\n", ticket.Status)
457		fmt.Fprintf(w, "资产 %s 当前状态: %s\n", asset.ID, asset.Status)
458		return nil
459	}
460	
461	func cmdHistory(args []string, w io.Writer) error {
462		var opts cmdOptions
463		var id string
464		fs := newFlagSet("history", &opts)
465		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
466		if err := parseFlags(fs, args); err != nil {
467			return err
468		}
469		if err := requireFlag(fs, id, "asset-id"); err != nil {
470			return err
471		}
472		s, err := openStore(opts.dataDir)
473		if err != nil {
474			return err
475		}
476		if s.findAsset(id) == nil {
477			return fmt.Errorf("未知资产编号 %q", id)
478		}
479		events := s.eventsOf(id)
480		if len(events) == 0 {
481			fmt.Fprintf(w, "资产 %s 暂无维修履历。\n", id)
482			return nil
483		}
484		fmt.Fprintf(w, "资产 %s 维修履历（共 %d 条）:\n", id, len(events))
485		for _, e := range events {
486			if e.Kind == eventAssign {
487				fmt.Fprintf(w, "[%s] %s 工单 %s: %s -> %s（%s）\n",
488					e.Time.Format("2006-01-02T15:04:05Z07:00"), e.Kind, e.TicketID,
489					assigneeDisplay(e.From), e.To, e.Content)
490				continue
491			}
492			fmt.Fprintf(w, "[%s] %s 工单 %s: %s\n",
493				e.Time.Format("2006-01-02T15:04:05Z07:00"), e.Kind, e.TicketID, e.Content)
494		}
495		return nil
496	}
