		if !sorted[i].start.Equal(sorted[j].start) {
			return sorted[i].start.Before(sorted[j].start)
		}
		return sorted[i].end.Before(sorted[j].end)
	})
	merged := make([]timeWindow, 0, len(sorted))
	for _, iv := range sorted {
		last := len(merged) - 1
		if last < 0 || iv.start.After(merged[last].end) {
			merged = append(merged, iv)
			continue
		}
		if iv.end.After(merged[last].end) {
			merged[last].end = iv.end
		}
	}
	return merged
}

// unionDurationSeconds 合并区间并集后，对总时长向下取整为整秒。
// 秒数由 Unix 秒与秒内纳秒分别计算，避免超大窗口下纳秒整数溢出。
func unionDurationSeconds(intervals []timeWindow) int64 {
	var total int64
	for _, iv := range mergeWindows(intervals) {
		total += floorSecondsBetween(iv.start, iv.end)
	}
	return total
}

// floorSecondsBetween 返回 hi-lo 的时长向下取整的整秒数（调用方保证 hi 晚于 lo）。
// time.Time.Unix() 是向下取整的秒刻度，秒内纳秒为非负偏移：
// 时长的小数部分为负时整体再减一秒。
func floorSecondsBetween(lo, hi time.Time) int64 {
	secs := hi.Unix() - lo.Unix()
	if hi.Nanosecond() < lo.Nanosecond() {
		secs--
	}
	return secs
}

