package main

import (
	"fmt"
	"sort"
	"time"
)

// 设备维修停机时长统计（只读）。
//
// 停机区间一律以履历时间为准，而不是工单记录里的重复时间字段：
//   - 起点为该工单的报修履历时间；
//   - 已关闭/已取消工单的终点为对应的关闭/取消履历时间；
//   - 未关闭工单的终点暂取输入窗口终点。
//
// 派工、转派不另起区间。统计仅计算区间与窗口 [start, end) 的交集；
// 同一资产不同工单的交集先合并为并集再求时长，避免重叠被重复计算；
// 不同资产分别计算。统计不写文件、不初始化目录、不追加履历。

// downtimeResult 为单项资产的统计结果。
type downtimeResult struct {
	AssetID  string
	Name     string
	Seconds int64
}

// downtimeAnomaly 描述一张终结工单“结束早于开始”的时间异常。
// 该异常只影响统计：它使整次查询整体失败，但不使台账失去一致性，
// 因此不拒绝原有查询与工单操作，也不自动改写时间。
type downtimeAnomaly struct {
	AssetID  string
	TicketID string
	Start    time.Time
	End      time.Time
}

func (e *downtimeAnomaly) Error() string {
	return fmt.Sprintf("资产 %s 工单 %s 的终结时间（%s）早于报修时间（%s），统计终止",
		e.AssetID, e.TicketID, e.End.Format(time.RFC3339Nano), e.Start.Format(time.RFC3339Nano))
}

// ticketOccupancy 是从履历提取的工单占用区间（半开放区间 [start,end)）。
// openEnd 为 true 表示工单未关闭，终点取窗口终点统计。
// openReportedAtEnd 标记未关闭工单在窗口终点或之后才报修，依规记零。
type ticketOccupancy struct {
	ticketID            string
	start               time.Time
	end                 time.Time
	openEnd             bool
	openReportedAtEnd   bool
}

// downtime 计算给定资产在窗口 [start, end) 内的停机秒数（向下取整）。
// 若该资产任一终结工单出现结束早于开始的时间异常，则整体失败。
// 若该资产没有任何工单占用，返回秒数 0。
func (s *store) downtime(assetID string, start, end time.Time) (int64, error) {
	intervals, err := s.occupancyIntervals(assetID, start, end)
	if err != nil {
		return 0, err
	}
	return unionDurationSeconds(intervals), nil
}

// occupancyIntervals 提取并裁剪到窗口内的占用交集区间，同资产内已按起点排序。
func (s *store) occupancyIntervals(assetID string, start, end time.Time) ([]timeWindow, error) {
	// 按工单归属及履历序号配对：先收集该资产每张工单的报修、关闭、取消履历时间。
	type span struct {
		ticketID string
		report   *Event
		close    *Event
		cancel   *Event
	}
	spans := map[string]*span{}
	var ticketOrder []string
	for i := range s.data.Events {
		e := &s.data.Events[i]
		if e.AssetID != assetID {
			continue
		}
		sp := spans[e.TicketID]
		if sp == nil {
			sp = &span{ticketID: e.TicketID}
			spans[e.TicketID] = sp
			ticketOrder.push(e.TicketID)
		}
		switch e.Kind {
		case eventReport:
			sp.report = e
		case eventClose, eventCancel:
			if sp.close != nil || sp.cancel != nil {
				// 一致性检查保证每张终结工单恰一条终结履历，正常不会走到。
				return nil, fmt.Errorf("数据内部错误：工单 %s 有多条终结履历", e.TicketID)
			}
			if e.Kind == eventClose {
				sp.close = e
			}}
	}
	return nil, nil
}

