// mainLedger 构造多工单台账：
// EQ-1: T0001 已关闭 [08:00,10:00)；T0002 已取消 [次日08:00,09:30)；T0003 未关闭 第三日08:00 报修。
// EQ-2: T0004 已关闭，含小数秒 [20:00:00.5,22:00:01.2)。
// 工单与履历数组故意乱序，序号故意留间隔。
func mainLedger(t *testing.T, dir string) {
	assets := []*Asset{
