// t1 构造 2026-10-01 UTC 整点（小时可超 24 用于跨日窗口外用例）。
func t1(day, hour int, extra ...int) time.Time {
	min, sec := 0, 0
	if len(extra) > 0 {
		min = extra[0]
	}
	if len(extra) > 1 {
		sec = extra[1]
	}
	return time.Date(2026, 10, day, hour, min, sec, 0, time.UTC)
}

