func TestFloorSecondsBetween(t *testing.T) {
	loc := time.FixedZone("UTC+8", 8*3600)
	lo := time.Date(2026, 10, 1, 8, 0, 0, 500_000_000, loc)
	hi := time.Date(2026, 10, 1, 10, 0, 1, 200_000_000, loc)
	// 时长 7200.7 秒，向下取整 7200。
	if got := floorSecondsBetween(lo, hi); got != 7200 {
		t.Fatalf("小数秒向下取整 = %d，想得到 7200", got)
	}
	lo2 := time.Date(2026, 10, 1, 8, 0, 0, 200_000_000, time.UTC)
	hi2 := time.Date(2026, 10, 1, 8, 0, 1, 800_000_000, time.UTC)
	if got := floorSecondsBetween(lo2, hi2); got != 1 {
		t.Fatalf("1.6 秒应取整为 1，得到 %d", got)
	}
}

